import { Component } from '@angular/core';

@Component({
  selector: 'app-mysql-elastic-logstash',
  templateUrl: './mysql-elastic-logstash.component.html',
  styleUrls: ['./mysql-elastic-logstash.component.css']
})


export class MysqlElasticLogstashComponent {

  tableOfContents: Array<string>[]= [
    ['section1','Introduction'],
    ['section2','Project Folder'],
    ['section3','Logstash Service Settings'],
    ['section4','MySql Service Settings'] 
  ];

  sections: Array<string>[]=[
    []
  ]

  ngOnInit() {      
    this.loadScript('./assets/prism.js', 'js');
    window.onload = () => {
      this.loadScript('./assets/main.js', 'js');
    };
  }

  loadScript(scriptUrl: string,Tipo: string) {
    if (Tipo=='js'){
      const script = document.createElement('script');
      script.type = 'text/javascript';
      script.src = scriptUrl;
      document.body.appendChild(script);
    }  else if (Tipo === 'css') {
      const link = document.createElement('link');
      link.rel='stylesheet'
      link.type = 'text/css';
      link.href = scriptUrl;
      document.head.appendChild(link);
    }   
  }

  scrollToSection(elementId: string): void {
    const elementToScrollTo = document.getElementById(elementId);
    if (elementToScrollTo) {
      elementToScrollTo.scrollIntoView({ behavior: 'smooth' });
    }
  }

}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Document</title>
</head>
<body>
    <app-header></app-header>
    <div class="global">        
        <div class="toc">
            <app-table-of-contents [tableOfContents]="tableOfContents"
                (scrollToElement)="scrollToSection($event)"></app-table-of-contents>
        </div>

        <div class="content">
            <div id="section1">
                <h2>Introduction</h2>
                <p>
                    My intention in this practices is help you to make a connection to mysql from ElasticSearch
                    and manage your queries like indices from kibana. It's important have a background in this tools, 
                    if you're new your can see this tutorials before.                
                </p>
                <ul>
                    <li><a routerLink="/practices/pyspark" routerLinkActive="active">MySQL</a></li>
                    <li><a routerLink="/practices/pyspark" routerLinkActive="active">ElasticSearch</a></li>
                </ul>
            </div>
            <div id="section2">
                <h2>Project Folder</h2>
                <p>

                </p>
                <p>

                </p>
                <p>

                </p>
            </div>
        </div>
    </div>
</body>
</html>
